"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["85220"],{3800(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>d,frontMatter:()=>o,contentTitle:()=>r,toc:()=>l,assets:()=>h});var i=JSON.parse('{"id":"qiangguo/downeverything","title":"","description":"Girl Who Likes Mathematics (Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n)","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/downeverything.md","sourceDirName":"qiangguo","slug":"/qiangguo/downeverything","permalink":"/en/qiangguo/downeverything","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"downeverything","title":"","hide_table_of_contents":true,"sidebar_label":"Completely Overthrow All Leftists, Rightists, Centrists, Oppose-Everything Factions, and Purist Factions!"},"sidebar":"qiangguoSidebar","previous":{"title":"\u67D0\u7F51\u53CB\u6F5C\u5728\u6027\u503E\u5411\u7684\u903B\u8F91\u8BBA\u8BC1\uFF01","permalink":"/en/qiangguo/sbsexualorientation"},"next":{"title":"Financial, Economic, and Related Departments Must Now Learn to Stay Ahead of Speculative Capital, Instead of Constantly \\"Running Behind\\"","permalink":"/en/qiangguo/aheadspeculativefund"}}'),a=n(74848),s=n(28453);let o={id:"downeverything",title:"",hide_table_of_contents:!0,sidebar_label:"Completely Overthrow All Leftists, Rightists, Centrists, Oppose-Everything Factions, and Purist Factions!"},r="Thoroughly Overthrow All Factions -- Left, Right, Center, Anti-Everything, and Pure Stream!",h={},l=[];function c(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"thoroughly-overthrow-all-factions----left-right-center-anti-everything-and-pure-stream",children:"Thoroughly Overthrow All Factions -- Left, Right, Center, Anti-Everything, and Pure Stream!"})}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"Girl Who Likes Mathematics (Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n)"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:'I. Leftist hypocrites, hurry up and strip off your rotten disguises of "the people," "class," and "equality."'}),"\n",(0,a.jsx)(t.p,{children:'Leftists, regardless of whether old or new factions, are all hypocrites in word and deed, inevitably engaged in fishing for fame, borrowing others\' power, feigning benevolence and righteousness, and flattering their superiors. Leftist hypocrites, hurry up and strip off and expose your rotten disguises of "the people," "class," and "equality."'}),"\n",(0,a.jsx)(t.p,{children:'In truth, in both old and new leftist thinking, "the people," "equality," and such are all inflated into the highest values, because in their framework, equality supposedly achieved through class struggle by the people has become the best cover. Both old and new leftists love to deploy these concepts, and the most enthusiastic are always the small-time lackeys. In China, such lackeys fill the streets.'}),"\n",(0,a.jsx)(t.p,{children:'In fact, the "people," "class," and "equality" that leftists hold aloft above their heads every day are like pheasant feathers. This pheasant-feather-style "people," "class," and "equality" has never existed. What exists is only the "people," "class," and "equality" manifested within certain real social relations -- and pheasant feathers are just pheasant feathers; pluck them all off and you have nothing but a floor covered in feathers.'}),"\n",(0,a.jsx)(t.p,{children:'Because leftists are accustomed to pheasant feathers, the "equality" on their heads is also a pheasant-feather-style disguise. Leftists are perpetually nostalgic for the so-called communal pot, because given the actual intelligence level of leftists -- same as the right -- they all think equality is like the scale-and-weight relationship when buying things at market. Little do they know that this view of equality belongs to the most feeble-minded kind. Left and right are essentially both the infantile faction.'}),"\n",(0,a.jsx)(t.p,{children:"For example, if a relation R satisfies: 1. aRa, 2. if aRb then bRa, 3. if aRb and bRc then aRc, then the scope of this relation R is vastly, vastly greater than the infantile faction's scale-and-weight relationship. The latter is merely the simplest and most boring case of the former. Of course, there are even more general forms of R, which we won't get into here. All real-world class, dictatorship, freedom, democracy, human rights, and so on can be described through a pile of things related to R. Without R, none of these things has any meaning."}),"\n",(0,a.jsx)(t.p,{children:'Only this R, situated at the center of the entire social structure, represents the true meaning of equality; in reality, equality is primary. But this R is not a fixed thing -- it is a complex space, and therefore possesses a certain historical possibility, arising and perishing moment to moment. It is not like the infantile faction\'s broken toys of freedom, democracy, and human rights, or the leftist faction\'s rotten disguises of "the people," "class," and "equality" -- all abstract concepts.'}),"\n",(0,a.jsx)(t.p,{children:"II. Infantile faction kiddies, hurry up and throw your broken toys of freedom, democracy, and human rights into the trash."}),"\n",(0,a.jsx)(t.p,{children:"The infantile faction, regardless of age, are all intellectually children, inevitably whispering to each other, making a racket, relieving themselves wherever they please, and wailing like ghosts. Infantile faction kiddies, hurry up and throw your broken toys of freedom, democracy, and human rights into the trash."}),"\n",(0,a.jsx)(t.p,{children:"In fact, in the latest infantile faction thinking, democracy and human rights are no longer regarded as the highest values, because in their framework, the so-called innate freedom of capital no longer needs any disguise. Yet the old-school infantile faction still intentionally or unintentionally invokes these concepts, and the most enthusiastic are the small-time lackeys. In China, such lackeys fill the streets."}),"\n",(0,a.jsx)(t.p,{children:"In fact, the freedom, democracy, and human rights that the infantile faction chews and sucks on all day long are like turtle fur and rabbit horns -- things that don't exist. This turtle-fur-and-rabbit-horn-style freedom, democracy, and human rights have never existed. What exists is only the freedom, democracy, and human rights manifested within certain real social relations. The latter have always existed -- it's just that for certain types of people there is too much, and for others too little."}),"\n",(0,a.jsx)(t.p,{children:"Because the infantile faction has worn turtle-fur spectacles for so long, in their eyes equality has also become something akin to the ethereal freedom, democracy, and human rights. The recently deceased idol of the infantile faction, old Mr. Li, at his advanced age still confused these two things, becoming a joke among all the infantile faction."}),"\n",(0,a.jsx)(t.p,{children:"The infantile faction sprays spittle at the so-called communal pot all day long, because given the infantile faction's intelligence level, they all think equality is like the scale-and-weight relationship when buying things at market. Little do they know this view of equality belongs to the most feeble-minded kind."}),"\n",(0,a.jsx)(t.p,{children:"For example, if a relation R satisfies: 1. aRa, 2. if aRb then bRa, 3. if aRb and bRc then aRc, then the scope of this relation R is vastly, vastly greater than the infantile faction's scale-and-weight relationship. The latter is merely the simplest and most boring case of the former. Of course, there are even more general forms of R, which we won't get into here. All real-world class, dictatorship, freedom, democracy, human rights, and so on can be described through a pile of things related to R. Without R, none of these things has any meaning."}),"\n",(0,a.jsx)(t.p,{children:"Only this R, situated at the center of the entire social structure, represents the true meaning of equality; in reality, equality is primary. But this R is not a fixed thing -- it is a complex space, and therefore possesses a certain historical possibility, arising and perishing moment to moment. It is not like the infantile faction's broken toys of freedom, democracy, and human rights -- all abstract concepts."}),"\n",(0,a.jsx)(t.p,{children:"III. Moderation is a crime -- the centrists who claim to oppose both left and right are a more nauseating bunch than either."}),"\n",(0,a.jsx)(t.p,{children:"That left and right are detestable needs no elaboration. But throughout history, in reality, and on forums, there is always a group that claims to be some kind of centrist faction, opposing both left and right, putting on a nauseating show of holding the bowl level. Moderation is a crime -- the centrists who claim to oppose both left and right are a more nauseating bunch than either left or right."}),"\n",(0,a.jsx)(t.p,{children:"Throughout history, centrists have without exception been spineless, slippery operators attempting to play both sides for profit. The outcome of every centrist has been either to tilt left or tilt right -- ultimately, which one wasn't co-opted in the end? Put bluntly, the so-called centrist faction is simply calculating that their scarcity gives them bargaining power. Left and right have too many people, so by creating a centrist faction, once left and right are evenly matched, the centrists become the crucial swing vote that can command a high price. Once left or right prevails, the centrists rush to embrace the winner faster than anyone else."}),"\n",(0,a.jsx)(t.p,{children:'The issue is not whether left, center, and right exist as such, but that word "faction." A so-called faction is just a nest of snakes and rats. This faction and that faction -- they might as well go be apple pies and pineapple pies instead. The so-called left, center, and right are all nothing but scheming tricks under a certain linguistic hegemony. Even if some faction claims to oppose all factions, it is still a faction that overthrows all factions -- no different.'}),"\n",(0,a.jsx)(t.p,{children:"Everything has always been fallen; what has fallen deserved to fall; what has not yet fallen will ultimately fall -- just as left faction, right faction, centrist faction, anti-everything faction all ultimately belong to one faction: the dead people faction. If there truly is any faction in this world, the dead people faction is the only real one. And then there are the so-called pure stream types, pretending to be profoundly mysterious, when in reality they're either scoundrels or people trying to fish in troubled waters -- merely seeking the shortcut of the recluse on Zhongnan Mountain. An un-factioned faction, equally a dead people faction."}),"\n",(0,a.jsx)(t.p,{children:"Left faction, right faction, centrist faction, anti-everything faction, pure stream faction -- all ultimately unified under the dead people faction. This is the only truth of history. Arguing all day about the similarities and differences between left and right -- what similarities and differences are there really? All similarities and differences cease to exist under the dead people faction. Since this is so, apart from those with ulterior motives, does this kind of argument have any reason to exist?"})]})}function d(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var i=n(96540);let a={},s=i.createContext(a);function o(e){let t=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);